using System.Text;
using System.Text.Json;
using System.Drawing.Imaging;
using System.IO.Compression;
namespace LocalChat;
partial class MainWindow {
 Message? workMessage;BrowserWindow? browser;int toolActions;
 void BeginWork(Message message){activeAgentTask=null;browserFresh=true;toolActions=0;message.StartedAt=DateTime.UtcNow;workMessage=message;RecordWork("Запрос принят · подготовка контекста");}
 void RecordWork(string text){if(workMessage==null||closing)return;var m=workMessage;if(m.Work.LastOrDefault()?.Text==text)return;if(text.StartsWith("Проход ")&&m.Work.LastOrDefault()?.Text.StartsWith("Проход ")==true)m.Work[^1].Text=text;else{m.Work.Add(new(){Text=text[..Math.Min(text.Length,500)]});if(m.Work.Count>80)m.Work.RemoveAt(1);}Post("work",new{id=m.Id,startedAt=m.StartedAt,steps=m.Work});}
 void ChooseOutput(){using var dialog=new FolderBrowserDialog{Description="Выбери папку для записи файлов NORA (можно на флешке). Существующие файлы не перезаписываются.",UseDescriptionForTitle=true};if(dialog.ShowDialog(this)==DialogResult.OK){settings.OutputFolder=dialog.SelectedPath;SaveSettings();}}
 void EnableBrowserTools(){BrowserAssist.Enable(settings);SaveSettings();}
 async Task<BrowserWindow> GetBrowser(){if(browser==null||browser.IsDisposed){browser=new(root,(host,problem)=>ConfirmAsync("Браузер · системная сеть",BrowserNetworkPolicy.Notice(host,problem),generation?.Token??default)){TopLevel=false,FormBorderStyle=FormBorderStyle.None,Dock=DockStyle.Fill};browserDock.Controls.Add(browser);browser.Show();browser.PageChanged+=()=>PublishBrowser();browser.HumanActivity+=BrowserHumanActivity;}await browser.Init();return browser;}
 OutputArtifact? FindArtifact(string id)=>current.Messages.SelectMany(m=>m.Artifacts).LastOrDefault(a=>id==""||a.Id==id);
 string StoredPath(OutputArtifact a)=>WorkspaceCore.ArtifactPath(Path.Combine(root,"artifacts"),a.RelativePath);
 void SaveArtifact(string id){var a=FindArtifact(id)??throw new Exception("Файл не найден");using var d=new SaveFileDialog{FileName=a.Name,Filter="Файл|*.*"};if(d.ShowDialog(this)==DialogResult.OK){File.Copy(StoredPath(a),d.FileName,true);Post("toast","Файл сохранён: "+d.FileName);}}
 OutputArtifact AddArtifact(Message message,string name,string kind,byte[] bytes){if(bytes.Length>25*1024*1024)throw new Exception("Результат больше 25 МБ.");var a=new OutputArtifact{Name=name,Kind=kind,Bytes=bytes.Length};a.RelativePath=current.Id+"/"+a.Id+"/"+name;string path=StoredPath(a);Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.WriteAllBytes(path,bytes);if(kind=="image")a.DataUrl="data:image/png;base64,"+Convert.ToBase64String(bytes);message.Artifacts.Add(a);SaveCurrent();return a;}
 OutputArtifact MakeZip(Message target,string? answer=null){
  var source=current.Messages.LastOrDefault(m=>m!=target&&m.Role=="assistant"&&m.State=="complete"&&(target.TaskId==""||m.TaskId==target.TaskId));
  var currentFiles=(target.TaskId!=""?current.Messages.Where(m=>m.TaskId==target.TaskId).SelectMany(m=>m.Artifacts):target.Artifacts).Where(a=>a.Kind!="zip").GroupBy(a=>a.Name,StringComparer.OrdinalIgnoreCase).Select(g=>g.Last()).ToList();
  string text=answer??(currentFiles.Count>0?"":source?.Text??"");
  var files=answer==null?(currentFiles.Count>0?currentFiles:source?.Artifacts.Where(a=>a.Kind!="zip").ToList()??new()):new List<OutputArtifact>();
  if(text.Length==0&&files.Count==0)throw new Exception("Сначала получи ответ или создай файл.");
  var entries=new List<(string Name,Func<Stream> Open)>();
  if(text.Length>0)foreach(var(name,body)in FileTools.Artifacts(text)){var content=Encoding.UTF8.GetBytes(body);entries.Add((name,()=>new MemoryStream(content,false)));}
  var names=entries.Select(e=>e.Name).ToHashSet(StringComparer.OrdinalIgnoreCase);
  foreach(var a in files){string name=names.Add(a.Name)?a.Name:a.Id[..8]+"-"+a.Name;string path=StoredPath(a);entries.Add((name,()=>File.OpenRead(path)));}
  return AddArtifact(target,"NORA-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".zip","zip",WorkspaceArchive.Create(entries));
 }
 static byte[] PngPreview(byte[] input){using var raw=new MemoryStream(input);using var image=Image.FromStream(raw);double scale=Math.Min(1,1280.0/Math.Max(image.Width,image.Height));using var resized=new Bitmap(image,new Size(Math.Max(1,(int)(image.Width*scale)),Math.Max(1,(int)(image.Height*scale))));using var bytes=new MemoryStream();resized.Save(bytes,ImageFormat.Png);return bytes.ToArray();}
 async Task<byte[]> ScreenImage(CancellationToken token){Hide();bool shown=browser?.Visible==true;browser?.Hide();try{await Task.Delay(300,token);var bounds=Screen.PrimaryScreen!.Bounds;using var image=new Bitmap(bounds.Width,bounds.Height);using(var g=Graphics.FromImage(image))g.CopyFromScreen(bounds.Location,Point.Empty,bounds.Size);using var bytes=new MemoryStream();image.Save(bytes,ImageFormat.Png);return PngPreview(bytes.ToArray());}finally{Show();if(shown)browser?.Show();}}
 async Task<string> ExecuteTool(ToolCall call,Message response,CancellationToken token,bool userRequested=false){token.ThrowIfCancellationRequested();if(userRequested&&call.tool=="browser_open")EnableBrowserTools();if(call.tool=="connector_request"){GetMcp(call.server);if(mcpClients.TryGetValue(call.server,out var existing)&&existing.Active)return "Сервис уже подключён: "+call.server+". Доступных функций: "+existing.Tools.Count+". Повторный вход не нужен.";response.ConnectionOffer=call.server;return "Для подключения нажми кнопку в карточке сервиса ниже. Подключение и доступ не предоставлены до подтверждения и входа.";}if(call.tool=="code_check")return await RunCodeCheck(call.name,call.text,call.server,token);if(call.tool=="browser_look"){if(string.IsNullOrWhiteSpace(settings.VisionModel))throw new Exception("Для распознавания картинки укажи локальную vision-модель: Настройки → Vision. Текст и элементы доступны через browser_snapshot без vision.");await WaitBrowserControl(token);if(!(await ApproveAsync("browser_look","Передать снимок текущей страницы локальной vision-модели? На нём могут быть личные данные.",token)))return "Пользователь запретил действие. Не повторять.";var image=await(await GetBrowser()).CapturePage(token);return await DescribeImages("Опиши видимую страницу для выполнения задачи: "+call.query,new(){"data:image/png;base64,"+Convert.ToBase64String(PngPreview(image))},token);}if(call.tool.StartsWith("mcp_"))return await ExecuteMcp(call,token);if(call.tool=="chat_memory_search")return ChatMemory.Search(current,call.query);if(call.tool=="create_file"){ArtifactWriter.Validate(call.name,call.text);if(!(await ApproveAsync("copy_to_output","Создать файл в чате: "+call.name,token)))return "Пользователь запретил действие. Не повторять.";var created=AddArtifact(response,call.name,"file",ArtifactWriter.Encode(call.name,call.text));return "Файл создан в чате: "+created.Name+"; id="+created.Id;}if(call.tool.StartsWith("browser_"))await WaitBrowserControl(token);if(call.tool is "browser_back" or "browser_forward" or "browser_reload" or "browser_tabs" or "browser_tab"){var nav=await GetBrowser();if(call.tool=="browser_tabs")return nav.TabSummary();if(!(await ApproveAsync(call.tool,"Браузер: "+call.tool+" · вкладка "+call.index,token)))return "Пользователь запретил действие. Не повторять.";await nav.NavigateTool(call.tool,call.index,token);return (await nav.Snapshot(token)).ToString();}string detail=call.tool switch{"browser_snapshot"=>"Прочитать видимые элементы страницы","browser_click"=>"Нажать элемент страницы №"+call.index+". Это может отправить форму или изменить данные.","browser_type"=>"Ввести текст в элемент №"+call.index+": "+call.text,"browser_scroll"=>"Прокрутить страницу", "browser_search"=>"Найти в Google: "+call.query,"browser_open"=>"Открыть публичную страницу: "+call.url,"browser_link"=>"Открыть ссылку №"+call.index+" текущей страницы","browser_read"=>"Прочитать видимый текст текущей страницы","browser_capture"=>"Сделать снимок страницы в чате","screen_capture"=>"Сделать снимок основного экрана и сохранить в чат. На нём могут быть личные данные.","copy_to_output"=>"Скопировать файл в папку: "+(settings.OutputFolder==""?"папка будет выбрана тобой":settings.OutputFolder),"make_zip"=>"Создать ZIP из последнего ответа/кода и снимков",_=>throw new Exception("Инструмент недоступен")};if(!(userRequested&&call.tool is "browser_open" or "browser_search")&&!(await ApproveAsync(call.tool,detail,token))){RecordWork("Действие отклонено пользователем: "+call.tool);return "Пользователь запретил действие. Не повторять без нового запроса.";}RecordWork(detail);
  switch(call.tool){
   case "screen_capture":{var a=AddArtifact(response,"Экран-"+DateTime.Now.ToString("HHmmss")+".png","image",await ScreenImage(token));return "Снимок экрана сохранён в чате: "+a.Name+"; id="+a.Id+". Текстовая модель не анализирует пиксели.";}
   case "make_zip":{var a=MakeZip(response);return "ZIP создан в чате: "+a.Name+"; id="+a.Id;}
   case "copy_to_output":{var a=FindArtifact(call.artifactId);if(a==null&&call.artifactId!="")throw new Exception("Файл с таким id не найден");a??=MakeZip(response);if(settings.OutputFolder==""){ChooseOutput();if(settings.OutputFolder=="")return "Папка не выбрана; копирования не было.";}token.ThrowIfCancellationRequested();string destination=WorkspaceCore.CopyNew(StoredPath(a),settings.OutputFolder,a.Name);RecordWork("Файл записан: "+destination);return "Готово. Файл скопирован: "+destination;}
   case "browser_capture":{var b=await GetBrowser();token.ThrowIfCancellationRequested();var a=AddArtifact(response,"Страница-"+DateTime.Now.ToString("HHmmss")+".png","image",PngPreview(await b.CapturePage(token)));return "Снимок страницы сохранён: "+a.Name+"; id="+a.Id;}
   case "browser_snapshot":{var b=await GetBrowser();return (await b.Snapshot(token)).ToString();}
   case "browser_click":{var b=await GetBrowser();await b.ActOnElement(call.index,null,token);await Task.Delay(400,token);return (await b.Snapshot(token)).ToString();}
   case "browser_type":{var b=await GetBrowser();await b.ActOnElement(call.index,call.text,token);return (await b.Snapshot(token)).ToString();}
   case "browser_scroll":{var b=await GetBrowser();await b.ScrollPage(call.index,token);return (await b.Snapshot(token)).ToString();}
   default:{var b=await GetBrowser();SetBrowserSplit(true);token.ThrowIfCancellationRequested();if(browserFresh&&call.tool is "browser_open" or "browser_search"){browserFresh=false;browserPreview="";}await WaitBrowserControl(token);PublishBrowser();if(call.tool=="browser_search")await b.Navigate(BrowserWindow.SearchUrl(call.query),token);else if(call.tool=="browser_open")await b.Navigate(call.url,token);else if(call.tool=="browser_link"){var before=await b.Read(token);if(call.index<1||call.index>before.Links.Count)throw new Exception("Нет ссылки с таким номером");await b.Navigate(before.Links[call.index-1].Url,token);}if(userRequested&&call.tool=="browser_open"){PublishBrowser();return "Браузер открыт. Вход выполняется пользователем на странице.";}await WaitBrowserControl(token);var page=await b.Read(token);await WaitBrowserControl(token);token.ThrowIfCancellationRequested();await UpdateBrowserPreview(b,token);string links=string.Join("\n",page.Links.Select((l,i)=>$"{i+1}. {l.Text} — {l.Url}"));return $"URL: {page.Url}\n{page.Title}\n{page.Text[..Math.Min(page.Text.Length,1800)]}\nССЫЛКИ:\n{links[..Math.Min(links.Length,1800)]}";}
  }
 }
 async Task RunQuick(ToolCall tool,string question){if(busy||settingUp||importing)throw new Exception("Дождись текущей операции.");current.Messages.Add(new(){Role="user",Text=question});var response=new Message{Role="assistant",State="streaming"};current.Messages.Add(response);if(current.Title=="Новый чат")current.Title=question[..Math.Min(question.Length,45)];current.Draft="";busy=true;generation=new();try{BeginWork(response);SaveCurrent();State();Post("busy",true);string result=await ExecuteTool(tool,response,generation.Token,true);response.Text=tool.tool=="browser_open"?"Браузер открыт справа. Войди в аккаунт самостоятельно на странице; пароль и код не отправляй в чат. Клик на странице передаёт управление тебе. После входа инструменты NORA могут читать видимую страницу и выполнять подтверждённые действия. Пароли и коды остаются ручными. Напиши следующую задачу или нажми «Проверить доступ».":result;response.State="complete";RecordWork("Действие завершено");}catch(OperationCanceledException){response.State="cancelled";response.Text="Остановлено пользователем.";}catch(Exception e){response.State="error";response.Text="Не выполнено: "+e.Message;RecordWork("Ошибка: "+e.Message);}finally{CompleteWork(response);}}
}
